results = []


def check(name, ok, detail=""):
    results.append(ok)
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def make_probe():
    probe = {"H": None, "poses": {}}

    def step(obs):
        if probe["H"] is None and obs.get("policy") and obs["policy"]["handoff"]:
            probe["H"] = obs["tick"]
        probe["poses"][obs["tick"]] = obs["base_pose"]
        return None

    return {"name": "probe", "step": step, "state": probe}, probe


def scenario_A(model, data):
    print("\nA: auto / hold, F9 takeover at handoff+100 and resume at handoff+200 (auto timeout 5 s)")
    tick = [0]
    src, probe = make_probe()

    def held(code):
        H = probe["H"]
        if H is None:
            return False
        k = tick[0] - H
        if code == glfw.KEY_F9:
            return k in (100, 101, 150, 151)          # take over; the second press (in teleop) must not hand back
        if code in (glfw.KEY_ENTER, glfw.KEY_DELETE):
            return k in (50, 51) or (code == glfw.KEY_ENTER and k in (200, 201))      # k = 50: auto mode, ignored
        if code == glfw.KEY_DOWN:
            return 110 <= k <= 124
        if code == glfw.KEY_SPACE:
            return 125 <= k <= 145
        return False

    s = run_episode(None, model, data, episode_cfg={**EPISODE_CFG, "timeout_after_handoff": 5.0}, held=held, loop_cfg={"tick_ref": tick},
                    extra_sources=lambda m, d: {"probe": src})
    sw = s["mode_switches"]
    check("switch log: initial auto, operator_key to teleop, operator_key back (Enter / Delete in auto and F9 in teleop did nothing)", [(m["from"], m["to"], m["cause"]) for m in sw] ==
          [("teleop", "auto", "initial"), ("auto", "teleop", "operator_key"), ("teleop", "auto", "operator_key")], str([m["cause"] for m in sw]))
    H = probe["H"]
    moved = np.hypot(*(np.array(probe["poses"][H + 150][:2]) - np.array(probe["poses"][H + 105][:2])))
    check("the base moved under the operator", moved > 0.03, f"{1000 * moved:.0f} mm between handoff+105 and +150")
    still = np.hypot(*(np.array(probe["poses"][H + 100][:2]) - np.array(probe["poses"][H + 5][:2])))
    check("the base did not move under auto (hold stage)", still < 0.002, f"{1000 * still:.1f} mm")
    check("auto clock paused during operator control", abs(s["auto_time_after_handoff_s"] - 5.0) < 0.02 and abs(s["operator_time_s"] - 1.6) < 0.05,
          f"auto {s['auto_time_after_handoff_s']:.3f} s, operator {s['operator_time_s']:.3f} s")
    check("outcome TIMEOUT (auto)", s["outcome"] == "TIMEOUT" and s["timeout_kind"] == "auto", f"{s['outcome']} {s['timeout_kind']}")


def scenario_B(model, data):
    print("\nB: auto / request_operator, beaker teleported at ~46 s (under teleop)")
    s = run_episode(lambda m, d: make_request_operator_stage(), model, data,
                    extra_sources=lambda m, d: {"cheat": make_cheat_arm_stage(m, d, delay_s=44.6)})
    sw = s["mode_switches"]
    check("policy_request switch at the handoff, stage request_operator", len(sw) == 2 and sw[1]["cause"] == "policy_request" and sw[1]["to"] == "teleop"
          and sw[1]["stage"] == "request_operator" and abs(sw[1]["time"] - s["handoff_time"]) < 0.05, str(sw[-1]))
    check("auto clock stayed at ~0 (the request came on the first tick after handoff)", s["auto_time_after_handoff_s"] < 0.05, f"{s['auto_time_after_handoff_s']:.3f} s")
    check("SUCCESS with operator_assisted", s["outcome"] == "SUCCESS" and s["operator_assisted"], f"{s['outcome']} operator_time {s['operator_time_s']:.1f} s")


